def max_unique_split(s: str) -> int:
    n = len(s)
    used = set()
    best = 0

    def dfs(start: int) -> None:
        nonlocal best
        if start == n:
            best = max(best, len(used))
            return
        # Even one character per piece cannot beat `best` from here: prune.
        if len(used) + (n - start) <= best:
            return
        for end in range(start + 1, n + 1):
            piece = s[start:end]
            if piece not in used:
                used.add(piece)
                dfs(end)
                used.remove(piece)

    dfs(0)
    return best

