def max_sum(nums: list[int]) -> int:
    # top[d] = the two largest numbers whose largest digit is d.
    top = [[0, 0] for _ in range(10)]
    for x in nums:
        d = max(int(c) for c in str(x))
        first, second = top[d]
        if x > first:
            top[d] = [x, first]
        elif x > second:
            top[d] = [first, x]
    best = -1
    for first, second in top:
        if second > 0:                  # at least two numbers share this digit
            best = max(best, first + second)
    return best

def maximum_length(nums: list[int]) -> int:
    evens = sum(1 for x in nums if x % 2 == 0)
    odds = len(nums) - evens
    # Longest alternating parity subsequence, greedy from the first element.
    alternating = 1
    last = nums[0] % 2
    for x in nums[1:]:
        if x % 2 != last:
            alternating += 1
            last = x % 2
    return max(evens, odds, alternating)

def maximum_median_sum(nums: list[int]) -> int:
    arr = sorted(nums)
    n = len(arr)
    groups = n // 3
    # Medians are the elements at positions n-2, n-4, ..., counting down `groups` times.
    return sum(arr[n - 2 - 2 * i] for i in range(groups))

def clumsy(n: int) -> int:
    # Signed terms of the expression; * and / fold into the top term.
    terms = [n]
    ops = "*/+-"
    idx = 0
    for x in range(n - 1, 0, -1):
        op = ops[idx % 4]
        idx += 1
        if op == "*":
            terms[-1] *= x
        elif op == "/":
            t = terms[-1]            # integer division truncating toward zero
            terms[-1] = t // x if t >= 0 else -((-t) // x)
        elif op == "+":
            terms.append(x)
        else:
            terms.append(-x)
    return sum(terms)

