def moves_to_chessboard(board: List[List[int]]) -> int:
    n = len(board)
    first = board[0]
    # Every row must equal the first row or be its exact complement.
    for row in board:
        same = row[0] == first[0]
        for a, b in zip(row, first):
            if (a == b) != same:
                return -1

    def moves(bits: List[bool]) -> int:
        """bits[i] says whether item i is 'like item 0'; count swaps to alternate them."""
        ones = sum(bits)
        if ones not in (n // 2, (n + 1) // 2):
            return -1
        mismatch = sum(1 for i, b in enumerate(bits) if b != (i % 2 == 0))
        if n % 2 == 0:
            return min(mismatch, n - mismatch) // 2
        return mismatch // 2 if mismatch % 2 == 0 else (n - mismatch) // 2

    rows = moves([row[0] == first[0] for row in board])
    cols = moves([v == first[0] for v in first])
    if rows < 0 or cols < 0:
        return -1
    return rows + cols

