def count_subarrays(nums: List[int], k: int) -> int:
    total = 0
    ends_here = {}                    # AND value -> number of subarrays ending at current index
    for x in nums:
        nxt = {x: 1}
        for v, c in ends_here.items():
            w = v & x
            nxt[w] = nxt.get(w, 0) + c
        ends_here = nxt
        total += ends_here.get(k, 0)
    return total

