def minimum_connected_groups(intervals: List[List[int]], k: int) -> int:
    # Merge the existing intervals into disjoint, ordered groups.
    groups = []
    for s, e in sorted(intervals):
        if groups and s <= groups[-1][1]:
            if e > groups[-1][1]:
                groups[-1][1] = e
        else:
            groups.append([s, e])
    g = len(groups)
    best_merge = 0                       # most groups removed by one insertion
    j = 0
    for i in range(g):
