def min_runes_to_add(n: int, crystals: List[int], flow_from: List[int], flow_to: List[int]) -> int:
    adj = [[] for _ in range(n)]
    for a, b in zip(flow_from, flow_to):
        adj[a].append(b)

    # 1. Everything reachable from a crystal is already powered.
    powered = [False] * n
    queue = deque()
    for c in crystals:
        if not powered[c]:
            powered[c] = True
            queue.append(c)
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not powered[v]:
                powered[v] = True
                queue.append(v)

    # 2. Iterative Tarjan SCC over the unpowered nodes only.
    index = [-1] * n
    low = [0] * n
    comp = [-1] * n
    on_stack = [False] * n
    stack = []
    counter = 0
    ncomp = 0
    for start in range(n):
        if powered[start] or index[start] != -1:
            continue
        work = [(start, 0)]
        index[start] = low[start] = counter
        counter += 1
        stack.append(start)
        on_stack[start] = True
        while work:
            u, i = work[-1]
            if i < len(adj[u]):
                work[-1] = (u, i + 1)
                v = adj[u][i]
                if powered[v]:
                    continue
                if index[v] == -1:
                    index[v] = low[v] = counter
                    counter += 1
                    stack.append(v)
                    on_stack[v] = True
                    work.append((v, 0))
                elif on_stack[v]:
                    low[u] = min(low[u], index[v])
            else:
                work.pop()
                if work:
                    p = work[-1][0]
                    low[p] = min(low[p], low[u])
                if low[u] == index[u]:
                    while True:
                        w = stack.pop()
                        on_stack[w] = False
                        comp[w] = ncomp
                        if w == u:
                            break
                    ncomp += 1

    # 3. Count components with no incoming edge from a different unpowered component.
    has_incoming = [False] * ncomp
    for a, b in zip(flow_from, flow_to):
        if not powered[a] and not powered[b] and comp[a] != comp[b]:
            has_incoming[comp[b]] = True
    return sum(1 for x in has_incoming if not x)

def rectangle_area(rectangles: List[List[int]]) -> int:
    MOD = 10 ** 9 + 7
    events = []                                   # (x, +1 enter / -1 leave, rectangle index)
    for i, (x1, y1, x2, y2) in enumerate(rectangles):
        events.append((x1, 1, i))
        events.append((x2, -1, i))
    events.sort()

    def covered_length(active) -> int:
        """Length of the union of the y intervals of the active rectangles."""
        spans = sorted((rectangles[i][1], rectangles[i][3]) for i in active)
        total, cur_lo, cur_hi = 0, None, None
        for lo, hi in spans:
            if cur_hi is None or lo > cur_hi:
                if cur_hi is not None:
                    total += cur_hi - cur_lo
                cur_lo, cur_hi = lo, hi
            elif hi > cur_hi:
                cur_hi = hi
        if cur_hi is not None:
            total += cur_hi - cur_lo
        return total

    area = 0
    active = set()
    prev_x = events[0][0]
    for x, kind, i in events:
        if x > prev_x and active:
            area = (area + (x - prev_x) * covered_length(active)) % MOD
        prev_x = x
        if kind == 1:
            active.add(i)
        else:
            active.discard(i)
    return area

