def total_beauty(nums: List[int]) -> int:
    MOD = 10 ** 9 + 7
    V = max(nums)

    divisor_cache = {}

    def divisors_of(v: int) -> List[int]:
        if v not in divisor_cache:
            small, large = [], []
            d = 1
            while d * d <= v:
                if v % d == 0:
                    small.append(d)
                    if d * d != v:
                        large.append(v // d)
                d += 1
            divisor_cache[v] = small + large[::-1]
        return divisor_cache[v]

    # For each d, the scaled values (v // d) of its multiples, in array order.
    scaled = defaultdict(list)
    for v in nums:
        for d in divisors_of(v):
            scaled[d].append(v // d)

    f = {}                                   # f[d] = increasing subsequences with all elements divisible by d
    for d, vals in scaled.items():
        size = V // d
        tree = [0] * (size + 1)              # Fenwick tree over scaled values 1..size
        total = 0
        for x in vals:
            # count subsequences ending in a value smaller than x
            i = x - 1
            smaller = 0
            while i > 0:
                smaller += tree[i]
                i -= i & -i
            cnt = (smaller + 1) % MOD
            total += cnt
            i = x
            while i <= size:
                tree[i] = (tree[i] + cnt) % MOD
                i += i & -i
        f[d] = total % MOD

    # Exact gcd counts by inclusion exclusion from the top down (only d with f[d] > 0 matter).
    keys = sorted(f, reverse=True)
    answer = 0
    for idx, d in enumerate(keys):
        exact = f[d]
        if V // d <= len(keys):
            for m in range(2 * d, V + 1, d):
                if m in f:
                    exact -= f[m]
        else:
            for m in keys[:idx]:
                if m % d == 0:
                    exact -= f[m]
        exact %= MOD
        f[d] = exact
        answer = (answer + d * exact) % MOD
    return answer

def min_operations_to_make_median_k(nums: List[int], k: int) -> int:
    """Sort, fix the middle element to k, then clamp the two halves toward k."""
    arr = sorted(nums)
    n = len(arr)
    mid = n // 2
    ops = abs(arr[mid] - k)
    # left half must not exceed k
    for i in range(mid):
        if arr[i] > k:
            ops += arr[i] - k
    # right half must not drop below k
    for i in range(mid + 1, n):
        if arr[i] < k:
            ops += k - arr[i]
    return ops

def find_winning_player(skills: List[int], k: int) -> int:
    """One pass: track the current champion and its winning streak."""
    champion = 0
    streak = 0
    for i in range(1, len(skills)):
        if skills[i] > skills[champion]:
            champion = i
            streak = 1
        else:
            streak += 1
        if streak == k:
            return champion
    # nobody reached k during the pass: the strongest player wins forever
