def number_of_nodes(n: int, queries: List[int]) -> int:
    """Parity per node, then push parities down the heap shaped tree."""
    flip = [0] * (n + 1)
    for q in queries:
        flip[q] ^= 1
    # the parent of v is v // 2 and always has a smaller label
    for v in range(2, n + 1):
        flip[v] ^= flip[v // 2]
    return sum(flip[1:])

def can_convert_string(s: str, t: str, k: int) -> bool:
    """Count how many indices need each shift; the one numbered c needs move d + 26 * (c - 1)."""
    if len(s) != len(t):
        return False
    count = [0] * 26
    for a, b in zip(s, t):
        d = (ord(b) - ord(a)) % 26
        if d == 0:
            continue
        count[d] += 1
        # the count[d]-th index with shift d must use move d + 26 * (count[d] - 1)
        if d + 26 * (count[d] - 1) > k:
            return False
    return True

def min_reverse_operations(n: int, p: int, banned: List[int], k: int) -> List[int]:
    """BFS over positions; skip visited positions with a next pointer per parity."""
    dist = [-1] * n
    for b in banned:
        dist[b] = -2          # banned, treated as visited
    dist[p] = 0
    nxt = list(range(n + 2))  # nxt[i]: next candidate of the same parity

    def find(x: int) -> int:
        while nxt[x] != x:
            nxt[x] = nxt[nxt[x]]
            x = nxt[x]
        return x

    for i in range(n):
        if dist[i] != -1:
            nxt[i] = i + 2
    queue = deque([p])
    while queue:
        i = queue.popleft()
        # reversing window [l, l + k - 1] sends i to 2l + k - 1 - i
        lo = 2 * max(0, i - k + 1) + k - 1 - i
        hi = 2 * min(i, n - k) + k - 1 - i
        j = find(lo)
        while j <= hi:
            dist[j] = dist[i] + 1
            queue.append(j)
            nxt[j] = j + 2
            j = find(j)
    for b in banned:
        dist[b] = -1
    return dist

def get_maximum_consecutive(coins: List[int]) -> int:
    """Extend the makeable range [0, reach] greedily with sorted coins."""
    reach = 0
    for c in sorted(coins):
        if c > reach + 1:
            break           # amount reach + 1 can never be formed
        reach += c
    return reach + 1

