def number_of_beautiful_integers(low: int, high: int, k: int) -> int:
    """Digit DP: count numbers <= x with equal even/odd digit counts and x % k == 0."""

    def count(x: int) -> int:
        if x <= 0:
            return 0
        digits = list(map(int, str(x)))
        length = len(digits)

        @lru_cache(maxsize=None)
        def go(pos: int, tight: bool, started: bool, diff: int, rem: int) -> int:
            if pos == length:
                return 1 if started and diff == 0 and rem == 0 else 0
            top = digits[pos] if tight else 9
            total = 0
            for d in range(top + 1):
                next_tight = tight and d == top
                if not started and d == 0:
                    # still a leading zero: nothing counted yet
                    total += go(pos + 1, next_tight, False, 0, 0)
                else:
                    step = 1 if d % 2 == 0 else -1
                    total += go(pos + 1, next_tight, True, diff + step, (rem * 10 + d) % k)
            return total

        return go(0, True, False, 0, 0)

    return count(high) - count(low - 1)

