def transform_array(nums: List[int]) -> List[int]:
    """Count evens; the sorted parity array is that many zeros then ones."""
    evens = sum(1 for x in nums if x % 2 == 0)
    return [0] * evens + [1] * (len(nums) - evens)

def good_subtree_sum(vals: List[int], par: List[int]) -> int:
    """Bottom up merge of mask -> best score tables; masks are digit sets."""
    MOD = 10**9 + 7
    n = len(vals)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[par[v]].append(v)

    def digit_mask(x: int) -> int:
        """Bitmask of the digits of x, or -1 if a digit repeats."""
        mask = 0
        while x:
            d = x % 10
            if mask >> d & 1:
                return -1
            mask |= 1 << d
            x //= 10
        return mask

    masks = [digit_mask(v) for v in vals]
    # iterative post order: parents after their children
    order, stack = [], [0]
    while stack:
        u = stack.pop()
        order.append(u)
        stack.extend(children[u])

    table = [None] * n
    total = 0
    for u in reversed(order):
        cur = {0: 0}
        if masks[u] >= 0:
            cur[masks[u]] = vals[u]
        for c in children[u]:
            child = table[c]
            table[c] = None            # free memory
            if len(child) == 1:
                continue
            if len(cur) == 1:
                cur = child
                continue
            merged = dict(cur)
            for mb, vb in child.items():
                for ma, va in cur.items():
                    if ma & mb == 0:
                        m = ma | mb
                        s = va + vb
                        if s > merged.get(m, -1):
                            merged[m] = s
            cur = merged
        table[u] = cur
        total += max(cur.values())
    return total % MOD

def destroy_targets(nums: List[int], space: int) -> int:
    """Group targets by residue modulo space; best class, smallest seed."""
    counts = Counter(x % space for x in nums)
    best = max(counts.values())
    return min(x for x in nums if counts[x % space] == best)

