def fixed_ratio(s: str, num1: int, num2: int) -> int:
    """Prefix key num2 * zeros - num1 * ones; equal keys bound a valid substring."""
    seen = Counter([0])      # the empty prefix
    key = 0
    result = 0
    for ch in s:
        if ch == "0":
            key += num2
        else:
            key -= num1
        result += seen[key]
        seen[key] += 1
    return result

