def get_smallest_string(s: str) -> str:
    """Swap the first same parity adjacent pair that is out of order."""
    digits = list(s)
    for i in range(len(digits) - 1):
        a, b = int(digits[i]), int(digits[i + 1])
        if a % 2 == b % 2 and a > b:
            digits[i], digits[i + 1] = digits[i + 1], digits[i]
            break
    return "".join(digits)

def min_prefix_removal(nums: List[int]) -> int:
    """Length of everything before the longest strictly increasing suffix."""
    i = len(nums) - 1
    while i > 0 and nums[i - 1] < nums[i]:
        i -= 1
    return i

def find_integer(k: int, digit1: int, digit2: int) -> int:
    """BFS over numbers made of the two digits, in increasing order."""
    LIMIT = 2**31 - 1
    digits = sorted({digit1, digit2})
    queue = deque(d for d in digits if d != 0)
    while queue:
        x = queue.popleft()
        if x > k and x % k == 0:
            return x
        for d in digits:
            y = x * 10 + d
            if y <= LIMIT:
                queue.append(y)
    return -1

def vowel_strings(words: List[str], left: int, right: int) -> int:
    """Count words in the range starting and ending with a vowel."""
    vowels = set("aeiou")
    count = 0
    for i in range(left, right + 1):
        w = words[i]
        if w[0] in vowels and w[-1] in vowels:
            count += 1
    return count
